import requests

def check_health(job: dict) -> dict:
    host = job["host"]
    port = int(job.get("port", 80))
    resp = requests.get(f"http://{host}:{port}/healthz", timeout=3)
    return {"host": host, "status": resp.status_code, "body": resp.text[:500]}

export async function makeThumbnail(body: { imageUrl: string; width: number }): Promise<Buffer> {
  const res = await fetch(body.imageUrl);
  if (!res.ok) throw new Error(`upstream ${res.status}`);
  const input = Buffer.from(await res.arrayBuffer());
  return sharp(input).resize(body.width).png().toBuffer();
}

func probe(w http.ResponseWriter, r *http.Request) {
	addr := net.JoinHostPort(r.FormValue("host"), r.FormValue("port"))
	conn, err := net.DialTimeout("tcp", addr, 2*time.Second)
	if err != nil {
		fmt.Fprintf(w, "closed: %v\n", err)
		return
	}
	banner := make([]byte, 256)
	n, _ := conn.Read(banner)
	conn.Close()
	fmt.Fprintf(w, "open: %q\n", banner[:n])
}

