public bool CheckPassword(User user, string candidate)
{
    using var md5 = MD5.Create();
    var hash = md5.ComputeHash(Encoding.UTF8.GetBytes(candidate));
    var hex = Convert.ToHexString(hash);
    return string.Equals(hex, user.PasswordHash, StringComparison.OrdinalIgnoreCase);
}

