def convert(src: str, dst: str, quality: int) -> None:
    if not 1 <= quality <= 100:
        raise ValueError("quality out of range")
    subprocess.run(
        ["convert", "--", src, "-quality", str(quality), dst],
        check=True,
        timeout=60,
    )

if __name__ == "__main__":
    convert(sys.argv[1], sys.argv[2], int(sys.argv[3]))

