private static readonly string UploadRoot = Path.GetFullPath("/var/app/uploads") + Path.DirectorySeparatorChar;

public byte[] ReadUpload(string relative)
{
    var full = Path.GetFullPath(Path.Combine(UploadRoot, relative));
    if (!full.StartsWith(UploadRoot, StringComparison.Ordinal))
        throw new UnauthorizedAccessException("path escapes upload root");
    return File.ReadAllBytes(full);
}

import { createCipheriv, randomBytes } from 'crypto';

const key = Buffer.from(process.env.DATA_KEY_B64 ?? '', 'base64');
if (key.length !== 32) throw new Error('DATA_KEY_B64 must decode to 32 bytes');

export function seal(plaintext: string): string {
  const iv = randomBytes(12);
  const cipher = createCipheriv('aes-256-gcm', key, iv);
  const ct = Buffer.concat([cipher.update(plaintext, 'utf8'), cipher.final()]);
  return Buffer.concat([iv, cipher.getAuthTag(), ct]).toString('base64');
}
